/* From Uiverse.io by McHaXYT  - Tags: simple, minimalist, white, black, button, dark, light, modern */
.__UIV_SCOPE__ .button {
  padding: 15px 20px;
  border: none;
  outline: none;
  background-color: #151515;
  color: #eee;
  border-radius: 7px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.25s ease-out;
}

.__UIV_SCOPE__ .button:hover {
  transform: translateY(-3px);
}

.__UIV_SCOPE__ .button-span {
  color: #aaa;
}
